  "regulated_action": {
    "target_id": "t0",
    "description": "Attempting to change reservation dates for RS-77120 from 2025-10-10 to 2025-10-11 (check-in) and 2025-10-13 to 2025-10-14 (check-out) without confirming availability for the new dates (11–14 October) and without explicit user confirmation for the new proposed dates (12–15 October)."
